 applets/weather/ions/noaa/ion_noaa.h          |  1 +
 applets/weather/main.xml                      |  6 ++
 ...sma_applet_org.kde.plasma.weather.notifyrc |  8 +++
 applets/weather/qml/WarningsPage.qml          |  2 +-
 .../qml/config/ConfigWeatherStation.qml       |  7 +++
