-        Warning warning(static_cast<Warnings::PriorityClass>(priority), u"<p><b>%1</b></p>%2"_s.arg(headline, description));
+        Warning warning(static_cast<Warnings::PriorityClass>(priority), description);
+        if (!headline.isEmpty()) {
