diff --git a/applets/weather/ions/noaa/ion_noaa.cpp b/applets/weather/ions/noaa/ion_noaa.cpp
index 28346f1cc..5d77b058f 100644
--- a/applets/weather/ions/noaa/ion_noaa.cpp
+++ b/applets/weather/ions/noaa/ion_noaa.cpp
@@ -615,8 +615,11 @@ void NOAAIon::updateWeather()
         auto warnings = std::make_shared<Warnings>();

         for (const WeatherData::Alert &alert : m_weatherData->alerts) {
-            // TODO: Add a Headline parameter to the plugin and the applet
-            Warning warning(alert.priority, u"<p><b>%1</b></p>%2"_s.arg(alert.headline, alert.description));
+            Warning warning(alert.priority, alert.description);
+            if (!alert.headline.isEmpty()) {
+                warning.setHeadline(alert.headline);
+            }
+            warning.setIdentifier(alert.id);
             warning.setTimestamp(alert.startTime);
             warnings->addWarning(warning);
         }
@@ -1309,6 +1312,10 @@ void NOAAIon::readAlerts(KJob *job, const QByteArray &data)
         }

         auto alert = WeatherData::Alert();
+        // Updates of an alert get a new id, but keep the event tracking part of their VTEC code,
+        // e.g. "KPSR.FA.W.0044" in "/O.CON.KPSR.FA.W.0044.000000T0000Z-261124T1800Z/"
+        const QStringList vtec = properties[u"parameters"_s][u"VTEC"_s][0].toString().split(u'.');
+        alert.id = vtec.size() >= 6 ? vtec.mid(2, 4).join(u'.') : properties[u"id"_s].toString();
         alert.startTime = QDateTime::fromString(properties[u"onset"_s].toString(), Qt::ISODate);
         alert.endTime = QDateTime::fromString(properties[u"ends"_s].toString(), Qt::ISODate);
         alert.priority = mapSeverity(properties[u"severity"_s].toString());
