diff --git a/applets/weather/qml/main.qml b/applets/weather/qml/main.qml
index 10debeec6..03618668f 100644
--- a/applets/weather/qml/main.qml
+++ b/applets/weather/qml/main.qml
@@ -11,6 +11,9 @@ import QtQuick
 import org.kde.plasma.plasmoid
 import org.kde.kirigami as Kirigami
 import org.kde.plasma.core as PlasmaCore
+import org.kde.notification
+
+import org.kde.plasma.weatherdata as WeatherData

 PlasmoidItem {
     id: root
@@ -37,6 +40,58 @@ PlasmoidItem {
         }
     }

+    Instantiator {
+        id: warningsInstantiator
+        model: Plasmoid.configuration.notifyWarnings ? forecastControl.forecast?.warnings ?? null : null
+        delegate: QtObject {
+            required property string description
+            required property var headline
+            required property var identifier
+            required property int priority
+            readonly property string key: identifier || Qt.md5((headline ?? "") + description)
+        }
+        onObjectAdded: Qt.callLater(root.notifyNewWarnings)
+        onObjectRemoved: Qt.callLater(root.notifyNewWarnings)
+    }
+
+    Component {
+        id: warningNotificationComponent
+        Notification {
+            componentName: "plasma_applet_org.kde.plasma.weather"
+            eventId: "weatherWarning"
+            autoDelete: true
+            defaultAction: NotificationAction {
+                label: i18nc("@action:button", "Show details")
+                onActivated: root.expanded = true
+            }
+        }
+    }
+
+    function notifyNewWarnings() : void {
+        if (!warningsInstantiator.model) {
+            return;
+        }
+        const notified = Plasmoid.configuration.notifiedWarnings;
+        const keys = [];
+        for (let i = 0; i < warningsInstantiator.count; ++i) {
+            const warning = warningsInstantiator.objectAt(i);
+            if (!warning) {
+                continue;
+            }
+            keys.push(warning.key);
+            if (notified.includes(warning.key)) {
+                continue;
+            }
+            const notification = warningNotificationComponent.createObject(root, {
+                title: forecastControl.forecast?.station?.place ? i18nc("@title:notification %1 is a place name", "Weather alert for %1", forecastControl.forecast.station.place) : i18nc("@title:notification", "Weather alert"),
+                text: warning.headline || warning.description,
+                urgency: warning.priority >= WeatherData.Warnings.High ? Notification.HighUrgency : Notification.NormalUrgency,
+            });
+            notification.sendEvent();
+        }
+        Plasmoid.configuration.notifiedWarnings = keys;
+    }
+
     onWeatherPlaceInfoChanged: {
         if (weatherPlaceInfo.length > 0) {
             forecastControl.setUpdateInterval(root.updateInterval);
