+    case Identifier:
+        return warning.identifier().has_value() ? *warning.identifier() : QVariant();
     case Info:
         return warning.info().has_value() ? *warning.info() : QVariant();
     case Timestamp:
@@ -51,6 +55,8 @@ QHash<int, QByteArray> Warnings::roleNames() const
     QHash<int, QByteArray> roles;

     roles[Description] = "description";
+    roles[Headline] = "headline";
+    roles[Identifier] = "identifier";
     roles[Info] = "info";
     roles[Priority] = "priority";
     roles[Timestamp] = "timestamp";
@@ -103,6 +109,16 @@ QString Warning::description() const
     return m_description;
 }

+std::optional<QString> Warning::headline() const
+{
+    return m_headline;
+}
+
+std::optional<QString> Warning::identifier() const
+{
+    return m_identifier;
+}
+
 std::optional<QString> Warning::info() const
 {
     return m_info;
@@ -113,6 +129,16 @@ std::optional<QDateTime> Warning::timestamp() const
     return m_timestamp;
 }

+void Warning::setHeadline(const QString &headline)
+{
+    m_headline = headline;
+}
+
+void Warning::setIdentifier(const QString &identifier)
+{
+    m_identifier = identifier;
+}
+
 void Warning::setInfo(const QString &info)
 {
     m_info = info;
