  * "Info " + number, string, free text string, optional
  * "Timestamp " + number, string, free text string, optional
  */
@@ -39,6 +41,8 @@ public:
         Info,
         Priority,
         Timestamp,
+        Headline,
+        Identifier,
     };

     Q_ENUM(WarningModel);
@@ -85,15 +89,24 @@ public:

     Warnings::PriorityClass priority() const;
     QString description() const;
+    std::optional<QString> headline() const;
